class FactorizedItemEmbedding(nn.Module):
    def __init__(self, itemnum: int, hidden_units: int):
        super().__init__()
        self.rank = max(1, hidden_units // 2)
        self.factor_a = nn.Embedding(itemnum + 1, self.rank, padding_idx=0)
        self.factor_b = nn.Parameter(torch.empty(self.rank, hidden_units))
        nn.init.normal_(self.factor_a.weight, mean=0.0, std=1.0)
        nn.init.normal_(self.factor_b, mean=0.0, std=self.rank ** -0.5)

    def forward(self, item_ids: torch.Tensor) -> torch.Tensor:
        return self.factor_a(item_ids).matmul(self.factor_b)


